from pathlib import Path
import html
root=Path('artifacts/road-land')
views=[('coast-drive','Along the golden coast','Granular pavement, compacted shoulders and broken sandstone stacks.'),('forest-drive','A road through the redwoods','Needle-covered earth, green ferns and clearer transitions at the shoulder.'),('headlands-drive','The last stretch of coast','Wind-shaped ground, warm grasses and layered stone on the banks.'),('asphalt','The pavement, up close','Original aggregate, subtle tire wear, weathered paint and a sealed construction joint.'),('forest-floor','Under the trees','Soil and needles replace the former broad green surface.'),('coastal-bluff','The edge of the Pacific','Sand, damp shoreline material, irregular ground and exposed stone.'),('headland-slope','Shape and surface','Finer nearby land, eroded contours and rock that follows the slope.'),('station-approach','A familiar stop','The new road and ground materials carry through the station approaches.')]
cards=''.join(f'''<article class="card"><div class="compare" data-view="{key}"><img class="after" src="after/high-{key}.png" alt="{html.escape(title)} after the environment pass"><img class="before" src="before/high-{key}.png" alt="{html.escape(title)} before the environment pass"><span class="tag old">Before</span><span class="tag new">After</span><div class="divider"></div></div><div class="body"><h3>{title}</h3><p>{description}</p><label>Compare <input aria-label="Compare before and after: {title}" type="range" min="0" max="100" value="30"></label></div></article>''' for key,title,description in views)
models=''.join(f'<article class="card study"><img src="after/model-{key}.png" alt="{title} model study"><div class="body"><h3>{title}</h3><p>{description}</p></div></article>' for key,title,description in [('outcrop','Weathered sandstone','Angled fracture faces, uneven crowns and original mineral surface maps.'),('fern','Redwood ground fern','Nine curved fronds with folded leaflets and slender rachises.'),('scrub','Coastal sage & daisies','Silver-green lance leaves, woody stems and small ivory flowers.')])
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pacific Run · road and land</title><style>
*{box-sizing:border-box}body{margin:0;background:#122124;color:#eee9d6;font:16px/1.6 system-ui}main{max-width:1380px;margin:auto;padding:45px 30px 70px}small{color:#dab477;text-transform:uppercase;letter-spacing:.17em;font-size:12px}h1{font:500 clamp(34px,5vw,58px)/1.12 Georgia;margin:12px 0 18px;max-width:860px}h2{font-weight:500;margin:38px 0 18px}h3{font-size:20px;font-weight:500;margin:0 0 7px}p{max-width:840px;color:#afc0b8}nav{display:flex;gap:25px;flex-wrap:wrap;margin:25px 0}a{color:#e2c08b}a:focus-visible,button:focus-visible,input:focus-visible{outline:2px solid #efc78d;outline-offset:4px}.preset{display:flex;align-items:center;gap:10px;padding:15px 19px;background:#1b2e31;border-left:2px solid #c3a365}.preset span{margin-right:8px;color:#c1cbbc}button{font:inherit;background:#283d3d;border:1px solid #4b5d57;color:#d7dfcf;border-radius:4px;padding:7px 16px;cursor:pointer}button[aria-pressed=true]{background:#bd9b65;color:#172426;border-color:#d1b17a}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}.card{background:#1d3033;border:1px solid #384a48;border-radius:8px;overflow:hidden}.compare{position:relative;aspect-ratio:14/9;--split:30%;overflow:hidden}.compare img{position:absolute;width:100%;height:100%;object-fit:cover}.before{clip-path:inset(0 calc(100% - var(--split)) 0 0)}.divider{position:absolute;left:var(--split);height:100%;border-left:2px solid #dec89c;pointer-events:none}.tag{position:absolute;top:14px;background:#132424cc;padding:3px 10px;font-size:11px;letter-spacing:.12em;text-transform:uppercase}.old{left:13px}.new{right:13px}.body{padding:18px 20px}.body p{font-size:14px;margin:0 0 16px}label{display:flex;align-items:center;gap:15px;color:#c7d3c5;font-size:12px}input{flex:1;min-width:0;accent-color:#c7ab78}.studies{grid-template-columns:repeat(3,minmax(0,1fr))}.study img{width:100%;display:block;aspect-ratio:14/9;object-fit:cover}.note{font-size:13px;color:#b1bfb5;margin:18px 0 26px}.phone{width:220px;max-width:100%;border-radius:6px;border:1px solid #45564e}@media(max-width:760px){main{padding:30px 18px}.grid,.studies{grid-template-columns:1fr}.preset{flex-wrap:wrap}.preset span{width:100%}nav{gap:17px}}
</style><main><small>Pacific Run · road & land</small><h1>A better road through a richer landscape.</h1><p>The pavement has grain, wear and a history of repairs. Beyond it, sand meets weathered stone, needles gather under the redwoods, and ferns and coastal flowers break up the ground.</p><nav><a href="/">Go for a drive →</a><a href="/artifacts/world-life/world-gallery.html">The living coast →</a><a href="/artifacts/water/water-gallery.html">Explore the water →</a><a href="/artifacts/juice/detail-gallery.html">Vehicle collection →</a></nav><div class="preset"><span>Compare the graphics presets</span><button data-quality="high" aria-pressed="true">High</button><button data-quality="balanced" aria-pressed="false">Balanced</button></div><p class="note">Drag each comparison slider. The before and after views show the same locations under the same lighting.</p><div class="grid">'''+cards+'''</div><h2>Original details, built for the land</h2><div class="grid studies">'''+models+'''</div><h2>Along the road on a smaller screen</h2><img class="phone" src="after/phone-drive.png" alt="The updated coastal roadway in the phone driving view"><p class="note">Fine terrain nearby and simpler distant ground keep detail concentrated where you can see it.</p></main><script>
for(const card of document.querySelectorAll('.card')){const range=card.querySelector('input');if(range)range.addEventListener('input',()=>card.querySelector('.compare').style.setProperty('--split',range.value+'%'));}
for(const button of document.querySelectorAll('[data-quality]'))button.addEventListener('click',()=>{const quality=button.dataset.quality;for(const b of document.querySelectorAll('[data-quality]'))b.setAttribute('aria-pressed',String(b===button));for(const box of document.querySelectorAll('[data-view]')){box.querySelector('.before').src='before/'+quality+'-'+box.dataset.view+'.png';box.querySelector('.after').src='after/'+quality+'-'+box.dataset.view+'.png';}});
</script></html>'''
(root/'road-gallery.html').write_text(page,encoding='utf8')
